using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.RunModifiers;
using LittleLeo;
using LittleLeo.Events;
using NaughtyAttributes;
using Unity.Services.Analytics;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "EndOfBattleState", menuName = "Data/Battle/Game States/End Of Battle State")]
public class EndOfBattleState : GameState
{
	[Header("Map Handler")]
	[SerializeField]
	private MapHandler mapHandler;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnPlayerVictory;

	[SerializeField]
	private VoidEvent OnStoreAllCorruptedAnimalsPurified;

	[SerializeField]
	private VoidEvent OnEnteredMap;

	[SerializeField]
	private VoidEvent OnChangeToAstreaFirstPhaseScenario;

	[SerializeField]
	private BoolEvent OnFadeVictoryPanel;

	[SerializeField]
	private VoidEvent OnAfterRewardFadeInCanvasAndUpdateEventsPanel;

	[Header("Between Battle")]
	[SerializeField]
	private bool removeStatusDiceBetweenBattle;

	[SerializeField]
	private bool moveAllDiceOnDiscardToBag;

	[SerializeField]
	private PlayerDiceInventoryData diceBag;

	[SerializeField]
	private PlayerDiceInventoryData discard;

	[SerializeField]
	private PlayerDiceInventoryData oncePerBattleDice;

	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private ReshuffleDiscardedDicesHandler reshuffleDiscardedDicesHandler;

	[SerializeField]
	private PlayerScoreXPData playerScoreXPData;

	[Header("Player Victory Panel")]
	[SerializeField]
	private GameObject finalVictoryPanelPrefab;

	[SerializeField]
	private GameObject finalVictoryDemoPanelPrefab;

	[SerializeField]
	private GameObject battleVictoryPrefab;

	[Header("Current Companions")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[Header("Achievements")]
	[SerializeField]
	private AchievementData purificationPioneerAchievementData;

	[Header("Difficulty Level")]
	[SerializeField]
	private DifficultyLevel astreaLevel;

	[Header("Demo")]
	[SerializeField]
	private GameController gameController;

	[NonSerialized]
	private bool init;

	[NonSerialized]
	private BattleVictoryPanel battleVictoryPanel;

	[NonSerialized]
	public bool GoToMapCoroutineWithoutDelays;

	[NonSerialized]
	public bool GoBackToEventsPanelInsteadOfMap;

	[NonSerialized]
	[ShowNonSerializedField]
	public bool EventBattleVictory;

	[NonSerialized]
	private Reward currentReward;

	public Reward CurrentReward => currentReward;

	public void OnReset()
	{
		init = false;
		currentReward = null;
		GoToMapCoroutineWithoutDelays = false;
		GoBackToEventsPanelInsteadOfMap = false;
		EventBattleVictory = false;
	}

	public override void OnStartState()
	{
		base.OnStartState();
		ReferenceSingleton<GameplayHandler>.Instance.ResetTimeScale();
		bool flag = mapHandler.IsBattleSetup || EventBattleVictory;
		if (!init && flag)
		{
			ReferenceSingleton<GameStateManager>.Instance.EndOfBattleStateQueueLock = true;
			ReferenceSingleton<AnalyticsManager>.Instance.BattleEndedAnalytics(victory: true);
			int num;
			if (gameController.IsDemo)
			{
				num = 0;
			}
			else
			{
				num = ((!ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAstreasHeartEnabled) ? 2 : 3);
				AstreaHeartReachedTimeAnalytics();
			}
			if (!gameController.IsDemo)
			{
				CalculateScoresXP();
			}
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterAchievement.OnStartEndOfBattleState();
			if (mapHandler.CurrentAreaIndex == 0 && mapHandler.CurrentAreaLevelIndex == 0)
			{
				purificationPioneerAchievementData.Unlock();
			}
			if (mapHandler.CurrentAreaIndex == num && mapHandler.BossBattle)
			{
				if (num == 2)
				{
					ReferenceSingleton<CoroutineHandler>.Instance.Run(ResetEndOfBattleAndSpawnBattleVictoryPanel(noReward: true));
					ReferenceSingleton<AnalyticsManager>.Instance.StarShardsPerAreaAnalytics(endOfBattleStateCalling: true);
				}
				else
				{
					RunPlayerFinalVictoryCoroutine(astreasGate: false);
				}
			}
			else
			{
				init = true;
				ReferenceSingleton<CoroutineHandler>.Instance.Run(ResetEndOfBattleAndSpawnBattleVictoryPanel(noReward: false));
			}
		}
		else
		{
			NextReward();
		}
	}

	private void AstreaHeartReachedTimeAnalytics()
	{
		if (saveSystem.HasAgreementSaveKey() && saveSystem.LoadAgreement() && mapHandler.CurrentAreaIndex == 2 && mapHandler.BossBattle)
		{
			int num = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentRunAnomalyLevel;
			if (num == -1)
			{
				num = 0;
			}
			Dictionary<string, object> eventParams = new Dictionary<string, object>
			{
				{
					"AstreaHeartReachedTime",
					ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.RunTotalTime
				},
				{
					"Character",
					ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName
				},
				{ "Anomaly", num }
			};
			ReferenceSingleton<AnalyticsManager>.Instance.RecordEventConvertingOldSDK("AstreaHeartReached", eventParams);
			AnalyticsService.Instance.Flush();
			Debug.Log("===== Astrea Heart Reached Time Analytics Flushed =====");
		}
	}

	public void CalculateScoresXP()
	{
		if (mapHandler.CurrentNodeData.NodeEnum != 0 && mapHandler.CurrentNodeData.NodeEnum != NodeEnum.BATTLEHARD && mapHandler.CurrentNodeData.NodeEnum != NodeEnum.BATTLEBOSS && mapHandler.CurrentNodeData.NodeEnum != NodeEnum.BATTLECORRUPTEDORACLE && (mapHandler.CurrentNodeData.NodeEnum != NodeEnum.EVENT || !ReferenceSingleton<TurnManager>.Instance.AmbushBattle))
		{
			return;
		}
		if (mapHandler.IsOnAstreasHeart)
		{
			if (mapHandler.CorruptedOracleBattle)
			{
				playerScoreXPData.NonAstreaBattleWonAddScoreXPItemData();
			}
		}
		else
		{
			playerScoreXPData.NonAstreaBattleWonAddScoreXPItemData();
		}
	}

	private IEnumerator ResetEndOfBattleAndSpawnBattleVictoryPanel(bool noReward)
	{
		if (!noReward)
		{
			ReferenceSingleton<BattleHandler>.Instance.EndOfBattleInitialize();
			ReferenceSingleton<TurnManager>.Instance.EndOfBattleInitialize();
		}
		else
		{
			currentCompanions.StoreCompanionsDice();
		}
		if (!ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation)
		{
			if (EventBattleVictory)
			{
				yield return new WaitForSeconds(0.4f);
			}
			else
			{
				yield return new WaitForSeconds(0.8f);
			}
		}
		if (EventBattleVictory)
		{
			EventBattleVictory = false;
			NextReward();
		}
		else if (!mapHandler.CorruptedOracleBattle)
		{
			GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(battleVictoryPrefab.name);
			battleVictoryPanel = @object.GetComponent<BattleVictoryPanel>();
			battleVictoryPanel.Initialize(noReward);
			OnPlayerVictory.Raise();
		}
		else
		{
			NextReward();
		}
	}

	public IEnumerator ResetPlayerDiceBag(bool makeDiceBagMatchDicePoolAfterMovingDice = false)
	{
		diceBag.InventoryItems.AddRange(oncePerBattleDice.InventoryItems);
		oncePerBattleDice.InventoryItems.Clear();
		diceBag.RemoveAfterBattleDice();
		discard.RemoveAfterBattleDice();
		if (removeStatusDiceBetweenBattle)
		{
			diceBag.RemoveAllStatusDice();
			discard.RemoveAllStatusDice();
		}
		if (moveAllDiceOnDiscardToBag)
		{
			yield return ReferenceSingleton<CoroutineHandler>.Instance.Run(reshuffleDiscardedDicesHandler.ReshuffleDices(duringBattle: false));
		}
		if (makeDiceBagMatchDicePoolAfterMovingDice)
		{
			diceBag.SetInventoryItems(ReferenceSingleton<AssetsReference>.Instance.DicePool.InventoryItems);
		}
	}

	public void CollectAllRewardsButtonPressed()
	{
		OnFadeVictoryPanel.Raise(item: false);
		NextReward();
	}

	public void NextReward()
	{
		Debug.Log("-----------NEXT REWARD------------");
		if (mapHandler.CurrentReward != null)
		{
			if (mapHandler.CurrentReward.IsAnyRewardLeft())
			{
				if (mapHandler.IsOnAstreasHeart && astreaLevel.IsDontRecoverHeartsDifficultyLevelActive() && mapHandler.CurrentAreaLevelIndex > 0)
				{
					ReferenceSingleton<CoroutineHandler>.Instance.Run(GoToMapCoroutine(enterAstreasHeart: false));
					return;
				}
				ReferenceSingleton<GameStateManager>.Instance.EndOfBattleStateQueueLock = true;
				currentReward = mapHandler.CurrentReward.GetCurrentReward();
				Debug.Log("-----------CURRENT REWARD: " + currentReward);
				mapHandler.CurrentReward.GetReward();
				mapHandler.CurrentReward.IncreaseRewardsCounter();
				Debug.Log("-----------CURRENT REWARD COUNTER: " + mapHandler.CurrentReward.RewardsCounter);
				if (mapHandler.CurrentReward.RewardsCounter < mapHandler.CurrentReward.Rewards.Length)
				{
					Debug.Log("-----------NEXT REWARD: " + mapHandler.CurrentReward.GetCurrentReward());
				}
			}
			else
			{
				AllRewardsCollectedGoToMapOrToAstreasGate();
			}
		}
		else
		{
			AllRewardsCollectedGoToMapOrToAstreasGate();
		}
	}

	private void AllRewardsCollectedGoToMapOrToAstreasGate()
	{
		if (mapHandler.CurrentAreaIndex == 2 && mapHandler.BossBattle)
		{
			battleVictoryPanel.GoToAstreasGate(noReward: false);
		}
		else
		{
			ReferenceSingleton<CoroutineHandler>.Instance.Run(GoToMapCoroutine(enterAstreasHeart: false));
		}
	}

	private IEnumerator GoToMapCoroutine(bool enterAstreasHeart, System.Action destroyAstreasGateAction = null)
	{
		if (GoBackToEventsPanelInsteadOfMap)
		{
			OnAfterRewardFadeInCanvasAndUpdateEventsPanel.Raise();
			ReferenceSingleton<GameStateManager>.Instance.EndOfBattleState.GoBackToEventsPanelInsteadOfMap = false;
			yield break;
		}
		if (!enterAstreasHeart && !GoToMapCoroutineWithoutDelays && !ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation)
		{
			yield return new WaitForSeconds(0.5f);
		}
		else
		{
			yield return InvokeAlternatives.WaitForFrames(3);
		}
		init = false;
		if (mapHandler.CurrentAreaIndex == 0)
		{
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterProgression.FirstChestPicksCounter == 0)
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterProgression.FirstChestPicksCounter = 2;
				saveSystem.SaveCurrentCharacterFirstChestPicksCounter();
			}
			else if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterProgression.FirstChestPicksCounter == 2)
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterProgression.FirstChestPicksCounter = 4;
				saveSystem.SaveCurrentCharacterFirstChestPicksCounter();
			}
		}
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HiddenAnomalyLevelFirstBossDefeatedStartBattleOnSecondBoss)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.HiddenAnomalyLevelFirstBossDefeatedStartBattleOnSecondBoss = false;
			saveSystem.SaveHiddenAnomalyLevelFirstBossDefeatedStartBattleOnSecondBoss();
		}
		saveSystem.SaveDiceInventoryCompanionOmenPlayerRun();
		saveSystem.SaveOnBattle(value: false);
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.MapState);
		if (mapHandler.IsPlayerAtTheBeginningOfTheFirstChapterMap())
		{
			DraftDiceRunModifier draftDiceRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.DraftDiceRunModifier;
			if (draftDiceRunModifier != null)
			{
				draftDiceRunModifier.EndedDraftingDice();
			}
		}
		yield return new WaitForSeconds(0.25f);
		OnStoreAllCorruptedAnimalsPurified.Raise();
		OnEnteredMap.Raise();
		if (enterAstreasHeart)
		{
			destroyAstreasGateAction();
		}
		if (!enterAstreasHeart && mapHandler.IsOnAstreasHeart && mapHandler.CurrentAreaLevelIndex == mapHandler.Map.MapLevels.Count - 2)
		{
			OnChangeToAstreaFirstPhaseScenario.Raise();
		}
		GoToMapCoroutineWithoutDelays = false;
	}

	public void EnterAstreasHeart(System.Action destroyAstreasGateAction)
	{
		ReferenceSingleton<CoroutineHandler>.Instance.Run(GoToMapCoroutine(enterAstreasHeart: true, destroyAstreasGateAction));
	}

	public void RunPlayerFinalVictoryCoroutine(bool astreasGate)
	{
		ReferenceSingleton<CoroutineHandler>.Instance.Run(PlayerFinalVictoryCoroutine(astreasGate));
	}

	private IEnumerator PlayerFinalVictoryCoroutine(bool astreasGate)
	{
		if (gameController.IsDemo)
		{
			yield return new WaitForSeconds(1.5f);
		}
		if (gameController.IsDemo)
		{
			UnityEngine.Object.Instantiate(finalVictoryDemoPanelPrefab);
		}
		else
		{
			currentCompanions.StoreCompanionsDice();
			UnityEngine.Object.Instantiate(finalVictoryPanelPrefab).GetComponent<PlayerLoseVictoryPanel>().Initialize(victory: true);
		}
		if (!astreasGate)
		{
			OnPlayerVictory.Raise();
		}
	}
}
